#!/usr/bin/env node
// #gui bundle build (spec §11.1, §11.2 rule 1a). Bundles src/main.ts (with @a-company/gnomon-contracts inlined, no
// runtime fetch of anything) into dist/bundle/{index.html, boot.js, styles.css, app.js}, hashes the tree with the
// kernel's `gnomon-bundle-tree:v1` definition (packages/gnomon/src/kernel/web/bundle.ts treeHashOf) and:
//   --embed  writes packages/gnomon/src/kernel/web/gui-bundle.ts (the files as opaque base64 + the pin literal)
//   --check  fails when that generated file is not byte-identical to a fresh build (the pin cannot drift)
import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'dist', 'bundle');
const EMBED = path.resolve(ROOT, '..', 'gnomon', 'src', 'kernel', 'web', 'gui-bundle.ts');

export async function buildFiles() {
  const r = await build({
    entryPoints: [path.join(ROOT, 'src', 'main.ts')],
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: 'es2022',
    minify: false,
    legalComments: 'none',
    charset: 'utf8',
    write: false,
    logLevel: 'silent',
  });
  const files = new Map();
  files.set('app.js', Buffer.from(`'use strict';\n${r.outputFiles[0].text}`, 'utf8'));
  for (const f of ['index.html', 'boot.js', 'styles.css']) files.set(f, readFileSync(path.join(ROOT, 'static', f)));
  return files;
}

export function treeHash(files) {
  const names = [...files.keys()].sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));
  const h = createHash('sha256').update('gnomon-bundle-tree:v1\n');
  for (const n of names) h.update(`${n}\0${createHash('sha256').update(files.get(n)).digest('hex')}\n`);
  return `sha256:${h.digest('hex')}`;
}

export function embedSource(files, hash) {
  const entries = [...files.keys()].sort().map((n) => `  ${JSON.stringify(n)}:\n    ${JSON.stringify(files.get(n).toString('base64'))},`);
  return `/**
 * @symbol #web-endpoint
 *
 * GENERATED by packages/gnomon-gui/scripts/build.mjs --embed — do not edit.
 * The pinned #gui bundle (M1.10 slice 1) as OPAQUE base64 bytes: the kernel
 * never evaluates, imports or inspects GUI code, it materializes these bytes
 * and compares a digest (spec §11.2 rule 1a, \`G-WEB-08\`). GUI_BUNDLE_HASH is
 * the gnomon-bundle-tree:v1 hash of exactly these files (test/web-units.test.ts
 * and packages/gnomon-gui \`--check\` prove both directions).
 */
export const GUI_BUNDLE_FILES_B64: Readonly<Record<string, string>> = Object.freeze({
${entries.join('\n')}
});

export const GUI_BUNDLE_HASH = ${JSON.stringify(hash)};
`;
}

const mode = process.argv[2] ?? '';
const files = await buildFiles();
const hash = treeHash(files);
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
for (const [n, b] of files) writeFileSync(path.join(OUT, n), b);
const src = embedSource(files, hash);
if (mode === '--embed') {
  writeFileSync(EMBED, src);
  process.stdout.write(`embedded ${files.size} files · ${hash}\n`);
} else if (mode === '--check') {
  let cur = '';
  try {
    cur = readFileSync(EMBED, 'utf8');
  } catch {}
  if (cur !== src) {
    process.stderr.write(`✕ gui-bundle.ts is stale: run \`npm run embed --workspace=@a-company/gnomon-gui\` (fresh ${hash})\n`);
    process.exit(1);
  }
  process.stdout.write(`✓ gui-bundle.ts matches the fresh build · ${hash}\n`);
} else process.stdout.write(`built ${files.size} files → dist/bundle · ${hash}\n`);
